// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // Assume the caller is the depositor account
        vm.assume(msg.sender == c.depositorAccount());

        // Record state before call
        uint64 preNumber = c.number();
        uint64 preTimestamp = c.timestamp();
        uint256 preBasefee = c.basefee();
        bytes32 preHash = c.hash();
        uint64 preSeqNum = c.sequenceNumber();
        bytes32 preBatcherHash = c.batcherHash();
        uint256 preL1FeeOverhead = c.l1FeeOverhead();
        uint256 preL1FeeScalar = c.l1FeeScalar();

        // Perform the call
        (bool success, ) = address(c).call(abi.encodeWithSelector(
            c.setL1BlockValues.selector,
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ));

        // The call must not revert
        assertTrue(success);

        // The state must have updated (at least one value changes)
        bool stateChanged = (
            c.number() != preNumber ||
            c.timestamp() != preTimestamp ||
            c.basefee() != preBasefee ||
            c.hash() != preHash ||
            c.sequenceNumber() != preSeqNum ||
            c.batcherHash() != preBatcherHash ||
            c.l1FeeOverhead() != preL1FeeOverhead ||
            c.l1FeeScalar() != preL1FeeScalar
        );
        assertTrue(stateChanged);
    }
}

